test('4163 1389固定附伤被真实反弹致死后停止石化及失败全强',()=>{
 for(let seed=0;seed<12;seed++){
  const s=make({moveId:10223,index:null},{soul:1389,omit:true,hp:1,seed});s.fighters[0].suitState.shield=10;s.fighters[0].stages.atk=1;timer(s,1,'低伤免疫返还',{threshold:1000});const o=turn(s);
  assert.equal(o.fighters[0].hp,0);assert.equal(o.fighters[1].ailments['石化'],undefined);assert.equal(o.fighters[0].stages.atk,1);assert.ok(o.damageEvents.some(e=>e.type==='fixed'&&e.targetSide===0&&e.hpLoss===1));
 }
});

test('4186 原魂印完整零伤不反制、重复受击整回合只反制一次',()=>{
 const zero=make({moveId:10004,index:null},{soul:1409});timer(zero,0,'当回合免伤');const z=turn(zero,920031,920040);assert.equal(z.fighters[0].soulState.dragonReactionRound,0);
 const multiple=make({moveId:10004,index:null},{soul:1409});shields.consume(multiple.fighters[0]);H.op(multiple,31,[2,2],920040);const m=turn(multiple,920031,920040);assert.equal(m.fighters[0].soulState.dragonReactionRound,1);assert.ok((m.damageEvents??[]).filter(e=>e.type==='fixed'&&e.sourceSide===0).length<=1);
});

test('4186 1672出手未满血固定吸取200按理论回复、满体不吸及百分比免疫不混同',()=>{
 const e=pick(1672)[0],s=turn(make(e,{hp:1000})),b=turn(make(e,{hp:1000,omit:true}));assert.equal(s.fighters[0].hp,1200);assert.equal(b.fighters[1].hp-s.fighters[1].hp,200);const full=turn(make(e));assert.equal(full.fighters[0].hp,9000);assert.equal(full.fighters[1].hp,turn(make(e,{omit:true})).fighters[1].hp);
 const immune=make(e,{hp:1000});timer(immune,1,'当回合免伤');const a=turn(immune);assert.equal(a.fighters[0].hp,1200);assert.equal(a.fighters[1].hp,9000);
 const blocked=make(e,{hp:1000});timer(blocked,0,'技能禁疗');assert.equal(turn(blocked).fighters[0].hp,1000);
});

test('4189 寒晶1HP正结算实际零损失仍触发，敌301HP不保护，完全免疫不触发',()=>{
 const s=make({moveId:10004,index:null},{soul:1411,hp:1,targetHp:300});s.fighters[0].stages.def=-1;H.op(s,29,[800],920042);const o=turn(s,920031,920042);assert.equal(o.damageEvents.at(-1).settledDamage,800);assert.equal(o.damageEvents.at(-1).hpLoss,0);assert.equal(o.fighters[0].hp,301);assert.equal(o.fighters[0].stages.def,0);
 const z=make({moveId:10004,index:null},{soul:1411,hp:200,targetHp:301});H.op(z,29,[800],920042);assert.equal(turn(z,920031,920042).fighters[0].hp,0);
 const immune=make({moveId:10004,index:null},{soul:1411,hp:200,targetHp:300});timer(immune,0,'当回合免伤');immune.fighters[0].stages.def=-1;H.op(immune,29,[800],920042);const a=turn(immune,920031,920042);assert.equal(a.fighters[0].hp,200);assert.equal(a.fighters[0].stages.def,-1);
});

test('4444 reductions ignored independently; Q-LIGHT-009 true bypasses immunity while fixed/percent immunity and barriers remain',()=>{
 for(const[type,id,args]of [['fixed',29,[100]],['percent',192,[10]],['true',1528,[100]]])for(const mode of ['ratio','flat','immune','shield','barrier']){const s=make(base,{soul:2085,omit:true}),b=structuredClone(s);s.fighters[1].ailments['诅咒']=4;H.entry(s);H.op(s,id,args,920031);H.op(b,id,args,920031);if(mode==='ratio'){timer(s,1,'固定百分比减伤',{fraction:.5});timer(s,1,'全伤害减半');}if(mode==='flat')timer(s,1,'伤害定额减免',{amount:20});if(mode==='immune')timer(s,1,type==='true'?'当回合免伤':'固定百分比免疫');if(mode==='shield')rules.add(s.fighters[1],10000,'remain-shield');if(mode==='barrier')rules.addBarrier(s.fighters[1],10000,'remain-barrier');const o=turn(s,920031);assert.equal(sum(o,type),(mode==='immune'||mode==='barrier')&&type!=='true'?0:sum(turn(b,920031),type),type+mode);if(mode==='shield')assert.equal(o.fighters[1].suitState.shield,10000);}
});

test('沉默通过真实第五标记封招且每回合扣八分之一，普通攻击可用',()=>{
 const s=game();assert.equal(s.moveDefinitions[key(0,4)].fifth,true);apply(s,0,'沉默',2);let o=turn(s,4);assert.equal(o.fighters[1].hp,1600);assert.equal(o.fighters[0].hp,1400);assert.equal(o.fighters[0].pp[key(0,4)],29);o=turn(o,3);assert.ok(o.fighters[1].hp<1600);assert.equal(o.fighters[0].hp,1200);assert.equal(o.fighters[0].ailments['沉默'],undefined);const next=turn(o,4);assert.ok(next.fighters[1].hp<o.fighters[1].hp);assert.equal(next.fighters[0].hp,1200);
 const im=game();apply(im,0,'沉默',1);timer(im,0,'当回合免伤');assert.equal(turn(im).fighters[0].hp,1600);
});

test('沸涌非暴击30%与暴击50%伤害下限，最终下限覆盖完全免伤',()=>{
 for(const crit of [false,true]){const s=game();apply(s,1,'沸涌');if(crit)timer(s,0,'必定暴击');const o=turn(s,0);assert.equal(o.fighters[0].lastAttackDamage,crit?800:480);const im=structuredClone(s);timer(im,1,'当回合免伤');assert.equal(turn(im,0).fighters[1].hp,crit?800:1120);apply(s,0,'臣服');assert.equal(turn(s,0).fighters[1].hp,crit?800:1120);}
 const zero=game();zero.moveDefinitions[key(0,0)].power=0;apply(zero,1,'沸涌');assert.equal(turn(zero,0).fighters[1].hp,1600);
});

test('雷解仅按实际红伤附加60%真实伤害，未命中或零伤不触发',()=>{
 const s=game();apply(s,0,'雷解');const o=turn(s,0),d=o.fighters[0].lastAttackDamage;assert.equal(1600-o.fighters[1].hp,d+Math.floor(d*.6));assert.equal(turn(s).fighters[1].hp,1600);
 const im=structuredClone(s);timer(im,1,'当回合免伤');assert.equal(turn(im,0).fighters[1].hp,1600);const miss=structuredClone(s);miss.moveDefinitions[key(0,0)].alwaysHit=false;timer(miss,0,'攻击必失');assert.equal(turn(miss,0).fighters[1].hp,1600);apply(s,0,'臣服');assert.equal(turn(s,0).fighters[1].hp,1600);
});
